{
  "hazard": {
    "classified": true,
    "signal_word": "위험",
    "pictograms": [
      {
        "code": "GHS02"
      },
      {
        "code": "GHS04"
      }
    ],
    "h_statements": [
      {
        "code": "H220",
        "text": "극인화성 가스",
        "line": "p2:L4"
      },
      {
        "code": "H280",
        "text": "고압가스 포함: 가열하면 폭발할 수 있음",
        "line": "p2:L5"
      }
    ],
    "p_statements": [
      {
        "code": "P210",
        "type": "예방",
        "text": "열, 고온의 표면, 스파크, 화염 및 그 밖의 점화원으로부터 멀리하시오. 금연",
        "line": "p2:L8"
      },
      {
        "code": "P377",
        "type": "대응",
        "text": "가스 누출 화재; 누출을 안전하게 막을 수 없다면 불을 끄려하지 마시오.",
        "line": "p2:L10"
      },
      {
        "code": "P381",
        "type": "대응",
        "text": "누출 시 모든 점화원을 제거하시오.",
        "line": "p2:L11"
      },
      {
        "code": "P403",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하시오.",
        "line": "p2:L13"
      },
      {
        "code": "P410+P403",
        "type": "저장",
        "text": "직사광선을 피하시오. 환기가 잘 되는 곳에 보관하시오.",
        "line": "p2:L14"
      }
    ],
    "other_hazards": [
      {
        "key": "기타 유해·위험성",
        "value": "경험과 제공된 정보에 의하면, 이 제품은 규정대로 사용 및 취급시 유해한 영향을 미치지 않습니다.",
        "line": "p2:L16"
      }
    ],
    "nfpa": {
      "health": 0,
      "fire": 0,
      "reactivity": 0,
      "special": null
    },
    "lines": {
      "pictograms": "p1:L30",
      "nfpa": "p1:L25"
    }
  },
  "narratives": [
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "다. 유해·위험성 분류기준에 포함되지 않는 기타 유해·위험성:",
      "start": "p2:L15",
      "end": "p2:L16"
    }
  ]
,
